public static boolean testCorrelations(double correlation1, double correlation2, int n1, int n2,
            double alpha)
        throws MathException
    {

        double p = getSignificance(correlation1, correlation2, n1, n2);

        if (p <= alpha) {
            return true;
        }
        else {
            return false;
        }
    }
